 static string DirectoryName{get{var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"-gridshift-report");return i>=0&&i+1<a.Length?a[i+1]:Path.GetFullPath("Docs/Validacao24/runtime");}}
