 IEnumerator Start(){deadline=Time.realtimeSinceStartup+300;Application.runInBackground=true;yield return new WaitForSecondsRealtime(3);
 Check(GridShiftProfiles.Login("casa24@exemplo.com","",out _),"perfil de teste isolado");Check(GridShiftProfiles.CreateCharacter(1,"Casa24",new GridShiftCharacterData{name="Luna",model=1},false,out _),"personagem criado");GridShiftProfiles.Activate(1,"Casa24");DeliverySaveStore.StartFresh=true;DeliverySaveStore.Pending=null;yield return SceneManager.LoadSceneAsync("SampleScene");yield return Ready();GridShiftTutorial.Restore(new TutorialSaveData{version=2,complete=true,step=15});GridShiftOperationsUI.Instance?.Close();GridShiftCampaignUI.Instance?.Close();var manager=DeliveryManager.Instance;var persistence=manager.GetComponent<DeliveryPersistence>();var cityPosition=player.transform.position;
 yield return WorldSession.Instance.RequestTransition("Apartment",player.transform);yield return new WaitForSeconds(.7f);player=InteractionFocus.PlayerFor(manager);var house=GridShiftApartment.Instance;var life=GridShiftLife.Instance;
 Check(SceneManager.GetActiveScene().name=="Apartment","casa usa cena Apartment separada");Check(house.transform.Find("Hallway")==null,"corredor externo removido");Check(house.GetComponent<GridShiftApartmentView>()==null&&house.transform.Find("Apartment city outlook and terrace")==null,"sem cidade duplicada nem varanda flutuante");Check(Vector3.Distance(player.transform.position,house.transform.TransformPoint(house.spawn))<.5f,"spawn direto dentro da casa");Check(Physics.Raycast(player.transform.position+Vector3.up,Vector3.down,2,~((1<<7)|(1<<8)|(1<<9)),QueryTriggerInteraction.Ignore),"spawn tem piso físico");
 var wall=house.GetComponentsInChildren<Renderer>(true).First(r=>r.name=="Int_Apt_01_Wall_01 (19)");Check(wall.enabled&&wall.GetComponents<Collider>().Any(c=>c.enabled),"passagem exterior vedada com parede e colisão");
 Check(Object.FindObjectsByType<TMP_Text>(FindObjectsSortMode.None).Any(t=>t.text=="FOME"),"HUD mostra FOME");Capture("casa-entrada");
 var shower=house.GetComponentsInChildren<GridShiftHomeUse>().First(h=>h.kind=="shower");var fx=player.gameObject.AddComponent<GridShiftHomeRoutineFX>();fx.Begin("wash",shower.transform,5);yield return new WaitForSeconds(.3f);var hands=player.CameraTransform.Find("Routine first person hands · wash");Check(hands!=null&&hands.GetComponentsInChildren<Transform>().Count(t=>t.name.StartsWith("Finger "))==8,"oito dedos e dois polegares nas mãos");Check(hands.GetComponentsInChildren<Transform>().Count(t=>t.name=="Thumb")==2,"polegares presentes");Check(hands.GetComponentsInChildren<Transform>().Count(t=>t.name=="Forearm")==2&&hands.GetComponentsInChildren<Transform>().Count(t=>t.name=="Upper arm sleeve")==2,"antebraços e braços completos");Check(hands.GetComponentsInChildren<MeshFilter>().All(m=>m.sharedMesh.name.Contains("Cube")),"mãos e braços usam geometria quadrada");Capture("maos-quadradas");fx.Dispose();yield return null;
 var bed=house.GetComponentsInChildren<GridShiftHomeUse>().First(h=>h.kind=="sleep");var avatar=player.transform.Find("Player customized appearance");var before=avatar.localPosition;var rotation=avatar.localRotation;var camera=player.CameraTransform.GetComponent<Camera>();int mask=camera.cullingMask;
 Check(life.Use("sleep",player,bed.transform),"ação real de dormir inicia");yield return new WaitForSeconds(.4f);fx=player.GetComponent<GridShiftHomeRoutineFX>();Check(fx!=null&&fx.LyingOnBed,"corpo colocado sobre a cama");Check(Mathf.Abs(Vector3.Dot(avatar.up,Vector3.up))<.05f,"personagem está horizontal");var mattress=bed.GetComponentsInChildren<MeshRenderer>().First(r=>r.name.StartsWith("Mattress"));Check(Mathf.Abs(avatar.position.y-mattress.bounds.max.y)<.2f,"corpo na altura do colchão");Check((camera.cullingMask&(1<<8))!=0,"câmera de sono mostra o personagem");var sleepAnimator=avatar.GetComponentInChildren<Animator>();var upper=sleepAnimator.GetBoneTransform(HumanBodyBones.LeftUpperArm);var lower=sleepAnimator.GetBoneTransform(HumanBodyBones.LeftLowerArm);Check(Mathf.Abs(Vector3.Dot((lower.position-upper.position).normalized,avatar.up))>.9f,"braços repousam ao lado do corpo");Capture("personagem-deitado");while(life.Acting)yield return null;Check(Vector3.Distance(avatar.localPosition,before)<.01f&&Quaternion.Angle(avatar.localRotation,rotation)<.1f,"acordar restaura pose e posição");log.AppendLine("WAKE camera="+camera.cullingMask+" prior="+mask+" energy="+life.State.energy+" blocked="+player.ControlsBlocked);Check(camera.cullingMask==mask&&life.State.energy>99&&!player.ControlsBlocked,"acordar restaura câmera, energia e controles");
 foreach(var otherBed in house.GetComponentsInChildren<GridShiftHomeUse>().Where(h=>h.kind=="sleep")){fx=player.gameObject.AddComponent<GridShiftHomeRoutineFX>();fx.Begin("sleep",otherBed.transform,2);yield return null;Check(fx.LyingOnBed&&Mathf.Abs(Vector3.Dot(avatar.up,Vector3.up))<.05f,"pose horizontal na cama "+otherBed.name);fx.Dispose();yield return null;}
 var appearance=GridShiftCharacter.Copy(GridShiftCharacter.Current);var basic=GridShiftCharacter.Copy(appearance);basic.model=-1;GridShiftCharacter.Commit(basic);yield return null;yield return null;fx=player.gameObject.AddComponent<GridShiftHomeRoutineFX>();fx.Begin("sleep",bed.transform,2);yield return new WaitForSeconds(.2f);Check(fx.LyingOnBed,"avatar original também deita sem mover o controlador");Capture("avatar-original-deitado");fx.Dispose();yield return null;GridShiftCharacter.Commit(appearance);yield return null;yield return null;
 Check(persistence.Save(),"save atual gravado");Check(GridShiftProfiles.Read(1,out var save,out _)&&save.homeLayoutVersion==24,"save identifica novo layout");save.homeLayoutVersion=23;save.activePlayerPosition=house.transform.position+new Vector3(-2.5f,.2f,-11);DeliverySaveStore.Pending=save;DeliverySaveStore.StartFresh=false;yield return SceneManager.LoadSceneAsync("SampleScene");yield return Ready();house=GridShiftApartment.Instance;manager=DeliveryManager.Instance;persistence=manager.GetComponent<DeliveryPersistence>();Check(Vector3.Distance(player.transform.position,house.transform.TransformPoint(house.spawn))<.5f,"save antigo migra do corredor para dentro da casa");Check(GridShiftTutorial.Completed,"tutorial completo preservado");
 yield return Use(house.GetComponentsInChildren<GridShiftWorldAction>().First(a=>a.title=="Sair de casa"));yield return new WaitForSeconds(1);while(WorldSession.Instance.Busy)yield return null;Check(SceneManager.GetActiveScene().name=="SampleScene","E na porta leva diretamente à cidade");player=InteractionFocus.PlayerFor(manager);Check(Vector3.Distance(player.transform.position,cityPosition)<1,"retorno preserva posição na cidade");yield return WorldSession.Instance.RequestTransition("Apartment",player.transform);yield return new WaitForSeconds(.5f);player=InteractionFocus.PlayerFor(manager);Check(GridShiftApartment.Instance.GetComponentsInChildren<GridShiftWorldAction>().Any(a=>a.title=="Sair de casa"),"saída funciona ao revisitar casa");Check(Object.FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Count(a=>a.isActiveAndEnabled)==1,"um listener de áudio ativo");Finish(true);
 }
 void Capture(string name){Directory.CreateDirectory(DirectoryName);var source=Camera.main;if(source==null)source=Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.isActiveAndEnabled);var overlays=Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var target=new RenderTexture(1920,1080,24);var prior=source.targetTexture;var active=RenderTexture.active;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=source;c.planeDistance=.8f;}source.targetTexture=target;Canvas.ForceUpdateCanvases();source.Render();RenderTexture.active=target;var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();File.WriteAllBytes(Path.Combine(DirectoryName,name+".png"),image.EncodeToPNG());source.targetTexture=prior;RenderTexture.active=active;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceOverlay;c.worldCamera=null;}target.Release();Object.Destroy(target);Object.Destroy(image);}
